    function registerNewZKChain(
        uint256 _chainId,
        address _zkChain,
        bool _checkMaxNumberOfZKChains
    ) public onlyChainAssetHandler {
        _registerNewZKChain(_chainId, _zkChain, _checkMaxNumberOfZKChains);
    }

